using labyItems.Services;
namespace labyItems.Pages.NonStandard;
public static class SpellCombatEditorPage{public static async Task<SpellService.SpellRaw?> EditAsync(INavigation nav,SpellService.SpellRaw s,bool damage){var a=new DruidEvocationService.EvocRaw{Damage=s.Damage==null?null:new(){amount=s.Damage.amount?.Select(x=>x.ToArray()).ToList(),type=s.Damage.type?.ToList(),DamageType=s.Damage.DamageType?.ToList(),ArmourApplies=s.Damage.ArmourApplies?.Select(x=>x.ToArray()).ToList(),ArmourType=s.Damage.ArmourType},Heal=s.Heal==null?null:new(){amount=s.Heal.amount?.Select(x=>x.ToArray()).ToList(),type=s.Heal.type?.ToList()}};var e=await EvocationCombatEditorPage.EditAsync(nav,a,damage);if(e==null)return null;if(damage){s.Damage=e.Damage==null?null:new(){amount=e.Damage.amount,type=e.Damage.type,DamageType=e.Damage.DamageType,ArmourApplies=e.Damage.ArmourApplies,ArmourType=e.Damage.ArmourType};s.legacyDamage=null;s.damType=null;s.MACApplies=null;}else s.Heal=e.Heal==null?null:new(){amount=e.Heal.amount,type=e.Heal.type};return s;}}
